\echo 'Session 155 — Matt 23 extras-tier cross-references migration starting...'
BEGIN;

-- Verse-lookup temp view. Mirrors the S154 view; retained for forward
-- compatibility even though Matt 23 surfaces only canon + enoch +
-- apocrypha + pseudepigrapha at S155.
CREATE TEMP VIEW _s155_xref_lookup AS
SELECT
    e.slug AS edition_slug,
    b.slug AS book_slug,
    c.chapter_number,
    v.verse_number,
    v.id AS verse_id
  FROM verses v
  JOIN chapters c ON v.chapter_id = c.id
  JOIN books    b ON c.book_id    = b.id
  JOIN editions e ON b.edition_id = e.id
 WHERE e.slug IN (
       'canon',
       'enoch',
       'jubilees',
       'jasher',
       'apocrypha',
       'apocrypha-charles-vol1',
       'pseudepigrapha',
       'adam-eve-conflict',
       'apocalypse-of-abraham',
       'ascension-isaiah',
       'sonnini-acts-29'
   );

-- ---------------------------------------------------------------------
-- Insert 21 extras-tier cross_references rows.
-- ---------------------------------------------------------------------
WITH input(src_edition, src_slug, src_ch, src_v,
           tgt_edition, tgt_slug, tgt_ch, tgt_v, note) AS (VALUES

  -- Thread 1: the-pride-and-religious-status-architecture-in-sirach
  ('canon', 'matthew', 23, 12, 'apocrypha', 'ecclesiasticus', 10, 14,
   '*Yahuah (God) has cast down the thrones of proud princes, and set up the meek in their stead.* Sirach (Ecclesiasticus) 10:14 names the wisdom-stream''s direct articulation of the kingdom-inversion-substance — the same Father''s-substance the King-of-Yashar''el (Israel) walks at Matt 23:12 (*whosoever shall exalt himself shall be abased; and he that shall humble himself shall be exalted*). The framework reads the verse in continuity with the Tanakh-substance the prophet-Mishlei (Proverbs) walks at Proverbs 16:18 and 29:23, the apostle-Ya''aqov (James) walks at James 4:6, 10, the apostle-Kefa (Peter) walks at 1 Peter 5:5-6, and the King-of-Yashar''el (Israel) walks at the foot-washing-substance of John 13:13-14. The kingdom-substance the King walks is the categorical-inversion of the leadership-status-substance the scribes-and-Pharisees walk; the wisdom-stream had named the architecture at the wisdom-instruction-register centuries before the gospel-pivot articulated it at the historical-register. The framework reads the verse against the inherited-Christian-pulpit''s collapse of the wisdom-stream into mere-piety-literature — the wisdom-stream carries the same Father''s-voice the Tanakh-prophets and the King-of-Yashar''el (Israel) walk-from, and Sirach 10:14 names the same kingdom-inversion-substance directly.'),

  ('canon', 'matthew', 23, 11, 'apocrypha', 'ecclesiasticus', 3, 18,
   '*The greater you are, the more humble thyself, and you shall find favour before Yahuah (God).* Sirach (Ecclesiasticus) 3:18 names the wisdom-stream''s direct articulation of the greater-you-are-more-humble-thyself substance the King-of-Yashar''el (Israel) walks at Matt 23:11 (*but he that is greatest among you shall be your servant*). The framework reads the verse against the inherited-religious-system-substance that walks-the-substance in reverse — the greater the religious-status-claim, the more elevation the leadership-substance walks-toward; Sirach 3:18 walks the kingdom-substance directly. The substance the King walks at Matt 18:1-5 (*except ye be converted, and become as little children, ye shall not enter into the kingdom of heaven*) and 20:25-28 (*whosoever will be great among you, let him be your minister*) is the same substance the wisdom-stream names — the kingdom-substance walks the greater-the-humbler architecture.'),

  ('canon', 'matthew', 23, 6, 'apocrypha', 'ecclesiasticus', 7, 4,
   '*Seek not of Yahuah (God) preeminence, neither of the king the seat of honour.* Sirach (Ecclesiasticus) 7:4 names the wisdom-stream''s direct articulation of the seek-not-preeminence substance — the same substance the King-of-Yashar''el (Israel) walks-against at Matt 23:6 (*love the uppermost rooms at feasts, and the chief seats in the synagogues*). The framework reads the verse in continuity with the kingdom-inversion-substance the King walks across the gospel — the religious-status-substance the leadership-substance walks-toward is the categorical-inversion of the kingdom-substance. The wisdom-stream had named the substance directly at the wisdom-instruction-register centuries before the gospel-pivot.'),

  ('canon', 'matthew', 23, 6, 'apocrypha', 'ecclesiasticus', 32, 1,
   '*If you be made the master of a feast, lift not thyself up, but be among them as one of the rest; take diligent care for them, and so sit down.* Sirach (Ecclesiasticus) 32:1 names THE direct wisdom-stream verbal-anchor for the master-of-the-feast-lift-not-thyself-up substance the King-of-Yashar''el (Israel) walks-against at Matt 23:6 (*the uppermost rooms at feasts*). The framework reads the verse against the inherited-religious-system-substance walking the wisdom-instruction-substance in-reverse — the religious-leadership-substance loves-the-uppermost-rooms while the wisdom-stream had explicitly named the lift-not-thyself-up substance the kingdom-substance walks-from. The substance the King walks at the foot-washing-substance of John 13:13-14 (*if I then, your Lord and Master, have washed your feet; ye also ought to wash one another''s feet*) walks the same substance the wisdom-stream names at Sirach 32:1 — the master''s-substance is the substance of taking-diligent-care-for-the-rest, not of lifting-thyself-up over them.'),

  -- Thread 2: the-corrupted-priesthood-and-false-credentialing-in-testaments-of-levi-and-wisdom-stream
  ('canon', 'matthew', 23, 13, 'pseudepigrapha', 'testaments-xii', 17, 3,
   '*And ye shall deal lawlessly together with Yashar''el (Israel), so He shall not bear with Jerusalem because of your wickedness; but the veil of the temple shall be rent, so as not to cover your shame.* Testaments XII Levi (file ch 17, canonical Testament of Levi 16) names the wisdom-stream''s direct articulation of the corrupted-priesthood-substance walking-lawlessly-with-Yashar''el (Israel) — the substance the King-of-Yashar''el (Israel) walks-against at Matt 23:13 (the first-woe — *ye shut up the kingdom of heaven against men*). The framework reads the verse as the wisdom-stream''s prefiguring of the substance the seven-woes walk-out at the Pharisaic-leadership-system at the first-coming. The veil-of-the-temple-rent substance walks-toward the historical-fulfillment at Matt 27:51 (*the veil of the temple was rent in twain from the top to the bottom*) — the same Tanakh-and-wisdom-stream-and-gospel-substance walks-from-prefiguring-to-fulfillment. The framework reads the substance in continuity with the system-not-people posture — the substance the wisdom-stream names is the leadership-substance walking-lawlessly, NOT the people-of-Yashar''el (Israel) categorically. (FRAMEWORK-MAJOR)'),

  ('canon', 'matthew', 23, 15, 'pseudepigrapha', 'testaments-xii', 20, 11,
   '*And in the seventh week shall become priests, (who are) idolaters, adulterers, lovers of money, proud, lawless, lascivious, abusers of children and beasts.* Testaments XII Levi (file ch 20, canonical Testament of Levi 17) names THE direct wisdom-stream verbal-anchor for the corrupted-priesthood-substance the King-of-Yashar''el (Israel) walks-against at Matt 23:15 (the second-woe — *ye compass sea and land to make one proselyte, and when he is made, ye make him twofold more the child of Gehinnom (Gehenna) than yourselves*). The framework reads the verse as FRAMEWORK-MAJOR — the wisdom-stream had named the substance of the priests-as-idolaters-adulterers-lovers-of-money-proud-lawless centuries before the gospel-pivot articulated the same substance at the seven-woes. The proselyte the Pharisaic-leadership-system makes becomes-twofold-the-child-of-Gehinnom (Gehenna) because the leadership-substance the proselyte is-converted-into is the same idolaters-adulterers-lovers-of-money-proud-lawless substance Testaments XII Levi names. The framework reads the substance in continuity with the contrary-to-Torah-test the apostle-Yochanan (John) names at 1 John 2:3-4 — the leadership-substance fails-the-test categorically. The same diagnostic operates in five costumes by the contrary-to-Torah-test: Pharisaic-rabbinic-system through ADDITION, Galatian-agitators through INVERSION, modern-institutional-Christianity through SUBTRACTION, modern-Hebrew-Roots-false-inclusion through COLLAPSE, Islam through TRANSFER. Same flesh-credential gospel. Same voiding of the Torah-substance. Four costumes on one antichrist architecture. (FRAMEWORK-MAJOR)'),

  ('canon', 'matthew', 23, 15, 'enoch', '1-enoch', 99, 2,
   '*Woe to them who pervert the words of uprightness, And transgress the eternal law, And transform themselves into what they were not [into sinners]: They shall be trodden under foot upon the earth.* 1 Enoch 99:2 names the wisdom-stream''s direct articulation of the pervert-the-words-of-uprightness-and-transform-themselves-into-sinners substance — the same substance the King-of-Yashar''el (Israel) walks-against at Matt 23:15 (the proselyte made-twofold-more-the-child-of-Gehinnom (Gehenna)). The framework reads the verse against the inherited-religious-system-substance that walks-the-substance in-reverse — the leadership-substance claims-to-walk-the-Torah while transgressing-the-eternal-law through the perversion-of-the-words-of-uprightness. The wisdom-stream had named the substance directly. The contrary-to-Torah-test the apostle-Yochanan (John) names at 1 John 2:3-4 is the standing-test the wisdom-stream had-already-named.'),

  ('canon', 'matthew', 23, 13, 'apocrypha', 'the-wisdom-of-solomon', 6, 4,
   '*Because, being ministers of his kingdom, you have not judged aright, nor kept the law, nor walked after the counsel of Yahuah (God).* Wisdom of Solomon 6:4 names the wisdom-stream''s direct articulation of the ministers-of-the-kingdom-have-not-judged-aright-nor-kept-the-law substance — the same substance the King-of-Yashar''el (Israel) walks-against at Matt 23:13 (the leadership-substance shuts-up-the-kingdom-of-heaven-against-men). The framework reads the verse as the wisdom-stream''s direct articulation of the contrary-to-Torah-test the apostle-Yochanan (John) names at 1 John 2:3-4 — the leadership-substance that-claims-to-be-ministers-of-the-kingdom while not-keeping-the-Torah-substance the Father gave fails the test categorically. The same diagnostic operates against the four-costumes per the framework''s reading — the Pharisaic-rabbinic-leadership at the first-coming, the Galatian-agitators-substance the apostle-Sha''ul (Paul) walks-against, modern-institutional-Christianity, modern-Hebrew-Roots-false-inclusion, and Islam. Same architecture. Same failure of the contrary-to-Torah-test. Different costumes.'),

  -- Thread 3: swearing-and-the-faithful-yes-and-nay-in-sirach
  ('canon', 'matthew', 23, 16, 'apocrypha', 'ecclesiasticus', 23, 9,
   '*Accustom not your mouth to swearing; neither use thyself to the naming of the Holy One.* Sirach (Ecclesiasticus) 23:9 names the wisdom-stream''s direct articulation of the accustom-not-thy-mouth-to-swearing substance — the same substance the King-of-Yashar''el (Israel) walks-from at Matt 5:33-37 (*swear not at all*) and walks-against at Matt 23:16-22 (the Pharisaic-oath-distinction-substance). The framework reads the verse in continuity with the Torah-substance the King walks-from at Vayikra (Leviticus) 19:12, Bamidbar (Numbers) 30:2, and Devarim (Deuteronomy) 23:21-23 — the Torah-substance is direct: every-vow-binds, every-oath-counts. The wisdom-stream had named the substance directly; the Pharisaic-oral-tradition-substance built the distinction-binding-and-non-binding-oaths-substance against-the-wisdom-stream and against-the-Torah-substance directly. The apostle-Ya''aqov (James) walks the same substance at James 5:12 (*let your yea be yea; and your nay, nay*).'),

  ('canon', 'matthew', 23, 22, 'apocrypha', 'ecclesiasticus', 23, 11,
   '*A man that useth much swearing shall be filled with iniquity, and the plague shall never depart from his house: if he shall offend, his sin shall be upon him.* Sirach (Ecclesiasticus) 23:11 names the wisdom-stream''s direct articulation of the man-that-useth-much-swearing-shall-be-filled-with-iniquity substance — the same substance the King-of-Yashar''el (Israel) walks-against at Matt 23:22 (*he that shall swear by heaven, sweareth by the throne of Elohim (God), and by him that sitteth thereon*). The framework reads the verse as the wisdom-stream''s direct corroboration of the seriousness of every-oath the King names. The Pharisaic-rabbinic-substance had-built-the-casuistic-distinction-substance between substantive-and-non-substantive oaths; the wisdom-stream had-named the substance directly — every-oath-counts, no-distinction-is-Torah-faithful.'),

  ('canon', 'matthew', 23, 18, 'apocrypha', 'ecclesiasticus', 27, 14,
   '*The talk of him that sweareth much makes the hair stand upright; and their brawls make one stop his ears.* Sirach (Ecclesiasticus) 27:14 names the wisdom-stream''s articulation of the talk-of-him-that-sweareth-much substance — the substance the King-of-Yashar''el (Israel) walks-against at Matt 23:18 (the Pharisaic-distinction-binding-the-oath-on-the-gift-but-not-on-the-altar substance). The framework reads the verse in continuity with the kingdom-substance walking-against the leadership-substance''s-casuistic-substance directly. The wisdom-stream had named the brawls-of-the-much-swearers substance; the leadership-substance walks-the-substance still under-the-religious-credential at the first-coming.'),

  -- Thread 4: the-double-heart-and-two-faces-in-sirach-testaments-of-asher-and-wisdom-of-solomon
  ('canon', 'matthew', 23, 25, 'apocrypha', 'ecclesiasticus', 1, 28,
   '*Distrust not the fear of Yahuah (God) when you are poor: and come not to him with a double heart.* Sirach (Ecclesiasticus) 1:28 names the wisdom-stream''s direct articulation of the come-not-with-a-double-heart substance — the same substance the King-of-Yashar''el (Israel) walks-against at Matt 23:25 (*ye make clean the outside of the cup and of the platter, but within they are full of extortion and excess*). The framework reads the verse as the wisdom-stream''s direct prefiguring of the heart-defilement-substance the King walks-from at Matt 15:10-20 and walks-against at Matt 23:25-26. The same Tanakh-substance the prophet-Shemu''el (Samuel) walks at 1 Samuel 16:7 (*Yahuah (the LORD) looketh on the heart*) is the substance Sirach 1:28 names directly — the come-not-with-a-double-heart substance is the substance the wisdom-stream walks-from and the King walks-from.'),

  ('canon', 'matthew', 23, 28, 'apocrypha', 'ecclesiasticus', 1, 29,
   '*Be not an hypocrite in the sight of men, and take good heed what you speak.* Sirach (Ecclesiasticus) 1:29 names THE direct wisdom-stream verbal-anchor for the be-not-an-hypocrite-in-the-sight-of-men substance — the same substance the King-of-Yashar''el (Israel) walks-against at Matt 23:28 (*even so ye also outwardly appear righteous unto men, but within ye are full of hypocrisy and iniquity*). The framework reads the verse as the wisdom-stream''s direct articulation of the hypocrisy-in-the-sight-of-men substance the seven-woes have-walked-out across the chapter. The Greek *hypokritai* (stage-actors who-play-a-part the heart-substance does-not-walk) is the same substance Sirach 1:29 names directly — the wisdom-stream had-named-the-substance centuries before the gospel-pivot.'),

  ('canon', 'matthew', 23, 28, 'pseudepigrapha', 'testaments-xii', 67, 1,
   '*But do not ye, my children, wear two faces like unto them, of goodness and of wickedness; but cleave unto goodness only, for Elohim (God) hath his habitation therein.* Testaments XII Asher (file ch 67, canonical Asher 3:1) names THE direct wisdom-stream verbal-anchor for the wear-not-two-faces substance — the same substance the King-of-Yashar''el (Israel) walks-against at Matt 23:28 (the outward-appearance-righteous against the within-full-of-hypocrisy-and-iniquity). The framework reads the verse as the wisdom-stream''s direct prefiguring of the whited-sepulchres-substance the King names at Matt 23:27-28. The same architecture the prophet-Yechezk''el (Ezekiel) walks at Ezekiel 13:10-12 (*daubed it with untempered morter*) is the substance Testaments XII Asher names directly — the wear-not-two-faces substance is the substance the wisdom-stream walks-from and the King walks-against. The framework reads this in continuity with the contrary-to-Torah-test the apostle-Yochanan (John) names at 1 John 2:3-4 — the two-faces substance is the substance that-fails the test categorically.'),

  ('canon', 'matthew', 23, 27, 'pseudepigrapha', 'testaments-xii', 69, 2,
   '*For they that are double-faced are guilty of a twofold sin; for they both do the evil thing and they have pleasure in them that do it, following the example of the spirits of deceit.* Testaments XII Asher (file ch 69, canonical Asher 5:2) names the wisdom-stream''s articulation of the double-faced-guilty-of-twofold-sin substance — the same substance the King-of-Yashar''el (Israel) walks-against at Matt 23:27 (*ye are like unto whited sepulchres, which indeed appear beautiful outward, but are within full of dead men''s bones, and of all uncleanness*). The framework reads the verse as the wisdom-stream''s direct articulation of the substance the seven-woes walk-against — the whited-sepulchres-substance the King names is the same double-faced-guilty-of-twofold-sin substance the wisdom-stream had-named.'),

  ('canon', 'matthew', 23, 25, 'apocrypha', 'the-wisdom-of-solomon', 5, 8,
   '*What has pride profited us? or what good has riches with our vaunting brought us?* Wisdom of Solomon 5:8 names the wisdom-stream''s articulation of the post-judgment-revealing of the wicked''s-pride-and-vaunting substance — the same substance the King-of-Yashar''el (Israel) walks-against at Matt 23:25 (the inside-full-of-extortion-and-excess substance). The framework reads the verse in continuity with the post-harvest-sifting per Red Line #11 and the *Grace, the Way, the New Heart, and the Mercy of Depart* section of framework-deep.md — the wicked''s-pride-and-vaunting is the substance the day-of-vindication-of-the-righteous-will-reveal. The substance the King walks-against at the inside-of-the-cup is the same substance the post-judgment-revealing in Wisdom of Solomon 5 names at the eschatological-register.'),

  -- Thread 5: the-blood-of-hevel-crying-and-the-mother-hen-gathering-in-1-enoch-and-2-esdras
  ('canon', 'matthew', 23, 33, 'enoch', '1-enoch', 22, 7,
   '*This place is the prison of the angels, and here they will be imprisoned for ever.* 1 Enoch 22:7 names the wisdom-stream''s articulation of the prison-of-the-angels substance — the framework''s reading-context for the *damnation of Gehinnom (Gehenna)* substance the King-of-Yashar''el (Israel) names at Matt 23:33 (*ye serpents, ye generation of vipers, how can ye escape the damnation of Gehinnom (Gehenna)?*). The framework reads the verse against the inherited-Christian-doctrine of eternal-conscious-torture-in-fire-for-the-merely-uninformed; the substance the King names is the prison-of-the-angels and the post-judgment-divisions per 1 Enoch 22''s articulation, NOT the Augustinian-substance the inherited-pulpit walks-from. The seed-of-the-serpent-substance the King names at v.33 walks the seed-war-substance from Bereshit (Genesis) 3:15 through the wheat-and-tares-substance of Matt 13:24-30 — the tares are bound and burned at the harvest; 1 Enoch 22 names the architecture of the spirits-of-the-dead-divisions-and-judgment the framework reads-from. (FRAMEWORK-MAJOR for the eschatology-architecture per the *Adam, the Sons of Adam, and the Tares* section of framework-deep.md.)'),

  ('canon', 'matthew', 23, 35, 'enoch', '1-enoch', 22, 14,
   '*This is the spirit which went forth from Abel, whom his brother Cain slew, and he makes his suit against him till his seed is destroyed from the face of the earth, and his seed is annihilated from amongst the seed of men.* 1 Enoch 22:14 names THE direct wisdom-stream verbal-anchor for the spirit-of-Hevel-(Abel)-makes-suit-against-Qayin-(Cain) substance — the substance the King-of-Yashar''el (Israel) names at Matt 23:35 (*the blood of righteous Hevel (Abel)*) walks-from. The framework reads the verse as FRAMEWORK-MAJOR — the wisdom-stream had named the architecture of Hevel-(Abel)''s-blood-crying-from-the-ground (Bereshit (Genesis) 4:10''s *the voice of thy brother''s blood crieth unto me from the ground*) at the spirits-of-the-dead-making-suit-architecture of 1 Enoch 22 centuries before the gospel-pivot. The apostolic-substance carries the same architecture forward at Hebrews 11:4 (*by faith Hevel (Abel) ... yet speaketh*) and Hebrews 12:24 (*to the blood of sprinkling, that speaketh better things than that of Hevel (Abel)*). The seed-war-substance the King names at v.33 (*ye serpents, ye generation of vipers*) walks the same Bereshit (Genesis) 3:15 substance the Hevel-(Abel)-blood-crying-substance walks-from — the wisdom-stream and the Tanakh and the gospel and the apostolic-substance all witness the same Hevel-(Abel)-as-first-righteous-blood architecture. *And his seed is annihilated from amongst the seed of men* the wisdom-stream names is the harvest-substance the wheat-and-tares-architecture walks-toward at Matt 13:24-30. (FRAMEWORK-MAJOR)'),

  ('canon', 'matthew', 23, 37, 'apocrypha', '2-esdras', 1, 30,
   '*I gathered you together, as a hen gathers her chickens under her wings: but now, what shall I do to you? I will cast you out from my face.* 2 Esdras (4 Ezra) 1:30 names THE direct wisdom-stream verbal-anchor for the *I gathered you together, as a hen gathers her chickens under her wings* substance the King-of-Yashar''el (Israel) walks at Matt 23:37 (*how often would I have gathered thy children together, even as a hen gathereth her chickens under her wings, and ye would not!*). The framework reads the verse as FRAMEWORK-MAJOR — the wisdom-stream had named the Father''s-mother-bird-gathering-the-children-of-Yerushalayim (Jerusalem)-substance in the same hen-gathers-her-chickens-under-her-wings figure-of-speech the King walks-from at the lament. The substance the King-speaks-with-the-Father''s-own-voice at the lament is the same substance 2 Esdras (4 Ezra) 1:30 names at the wisdom-stream-register. The framework reads the verse in continuity with the Tanakh-substance the prophet-Mosheh (Moses) walked at Devarim (Deuteronomy) 32:11-12 (*as an eagle stirreth up her nest, fluttereth over her young, spreadeth abroad her wings*), the Tehillim (Psalms) across 17:8, 36:7, 57:1, 61:4, 63:7, and 91:4 (*hide me under the shadow of thy wings* and parallels), Ruth 2:12 (*under whose wings thou art come to trust*), and the prophet-Yeshayahu (Isaiah) at Isaiah 31:5 (*as birds flying, so will Yahuah Tseva''ot (LORD of hosts) defend Yerushalayim (Jerusalem)*). The wisdom-stream and the Tanakh and the gospel all walk the same Father-as-mother-bird-gathering-the-children architecture. (FRAMEWORK-MAJOR for the ingathering-substance per Red Line #11)'),

  ('canon', 'matthew', 23, 34, 'apocrypha', '2-esdras', 1, 32,
   '*I sent to you my servants the prophets, whom you have taken and slain, and torn their bodies in pieces, whose blood I will require of your hands, says Yahuah (God).* 2 Esdras (4 Ezra) 1:32 names THE direct wisdom-stream verbal-anchor for the *I-sent-prophets-whom-you-have-taken-and-slain* substance — the same substance the King-of-Yashar''el (Israel) walks at Matt 23:34 (*wherefore, behold, I send unto you prophets, and wise men, and scribes: and some of them ye shall kill and crucify*) and the prophet-killing-pattern at vv.35-36 (*all the righteous blood shed upon the earth, from the blood of righteous Hevel (Abel) unto the blood of Zecharyah (Zechariah)*). The framework reads the verse as the wisdom-stream''s direct articulation of the prophet-killing-pattern the Tanakh-substance walks-from — the prophet-Yirmeyahu (Jeremiah) at Jeremiah 7:25-26 and 25:4 and 35:15 (*all my servants the prophets, daily rising up early and sending them*), the prophet-Nechemyah (Nehemiah) at Nehemiah 9:26 (*they slew thy prophets which testified against them*), and the prophet-Yeshayahu (Isaiah) at Isaiah 65:2 (*I have spread out my hands all the day unto a rebellious people*). The wisdom-stream and the Tanakh-prophets and the gospel-pivot all walk the same prophet-killing-pattern architecture; the apostolic-substance carries-the-same-substance-forward at Acts 7:51-53 (the apostle-Stephen at the stoning by the leadership-substance) and 2 Corinthians 11:24-25 (the apostle-Sha''ul (Paul)''s scourgings-in-the-synagogues). The substance the King walks at v.34 is the same substance 2 Esdras (4 Ezra) 1:32 names directly.'),

  ('canon', 'matthew', 23, 38, 'apocrypha', '2-esdras', 1, 33,
   '*Thus says the Almighty Yahuah (God), Your house is desolate, I will cast you out as the wind does stubble.* 2 Esdras (4 Ezra) 1:33 names THE direct wisdom-stream verbal-anchor for the *Your house is desolate* substance — the same substance the King-of-Yashar''el (Israel) walks at Matt 23:38 (*behold, your house is left unto you desolate*). The framework reads the verse as the wisdom-stream''s direct articulation of the house-left-desolate substance the Tanakh-substance walks-from — the prophet-Yirmeyahu (Jeremiah) at Jeremiah 12:7 (*I have forsaken mine house, I have left mine heritage*) and Jeremiah 22:5 (*this house shall become a desolation*) and the departure-of-the-Shekinah-substance the prophet-Yechezk''el (Ezekiel) walked at Ezekiel 10:18-19 and 11:22-23. The Father''s-Shekinah departed-the-First-Temple before the Babylonian-destruction; the Second-Temple the King-of-Yashar''el (Israel) walks-out-of at the close of Matt 23 is the Temple the Father''s-Shekinah did-not-fully-return-to in the post-exilic-substance (the prophet-Chaggai (Haggai) names the comparatively-empty substance at Haggai 2:3); and the King''s-departure-from-the-Temple at the close of this chapter is the substantial-substance the *house-left-desolate* names. The wisdom-stream and the Tanakh-prophets and the gospel-pivot all walk the same house-left-desolate architecture. (FRAMEWORK-MAJOR — the lament-substance walks the gathering-substance EVEN-at-the-moment-of-the-substantial-judgment of the leadership-substance the seven-woes have-walked-out; the substantial-judgment of the false-shepherds is the substance that-clears-the-way for the True-Shepherd''s-gathering per the prophet-Yechezk''el (Ezekiel) at Ezekiel 34:1-31; the substance walks-toward the surviving-third-substance the prophet-Zekharyah (Zechariah) walks at Zechariah 13:8-9 and the look-upon-me-whom-they-have-pierced substance at Zechariah 12:10.)')

)
INSERT INTO cross_references (source_verse_id, target_verse_id, source, note, tier_required)
SELECT sv.verse_id, tv.verse_id, 'manual', i.note, 'extras'::content_tier
  FROM input i
  JOIN _s155_xref_lookup sv ON sv.edition_slug   = i.src_edition
                           AND sv.book_slug      = i.src_slug
                           AND sv.chapter_number = i.src_ch
                           AND sv.verse_number   = i.src_v
  JOIN _s155_xref_lookup tv ON tv.edition_slug   = i.tgt_edition
                           AND tv.book_slug      = i.tgt_slug
                           AND tv.chapter_number = i.tgt_ch
                           AND tv.verse_number   = i.tgt_v
 WHERE sv.verse_id <> tv.verse_id
ON CONFLICT (source_verse_id, target_verse_id, source) DO NOTHING;

