-- Thread 1 (sort 337): the-pride-and-religious-status-architecture-in-sirach
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'the-pride-and-religious-status-architecture-in-sirach',
       'The pride-and-religious-status architecture — Sirach''s wisdom-stream witness to the kingdom-inversion the King walks-against at Matt 23:1-12',
       'Matt 23:1-12''s introduction — *the scribes and the Pharisees sit in Mosheh''s (Moses''s) seat* + *they say, and do not* + the heavy-burdens-the-leadership-substance-binds-on-others-while-not-moving-them-with-one-finger + the for-to-be-seen-of-men display of broadened-Tefillin and enlarged-Tsitsit (the *making-broad* and *enlarging* of the Torah-substance for the display, NOT the Tefillin or Tsitsit themselves — the King-of-Yashar''el (Israel) walked-the-Tsitsit himself per Matt 9:20 and 14:36) + the love-of-uppermost-rooms-at-feasts-and-chief-seats-in-the-synagogues + the categorical-rejection-of-religious-paternity-titles (NOT against the Hebrew-teaching-relationship the apostles still walked or the natural-father-honor the King walked at the cross at John 19:26-27, but against the substance-of-religious-status the leadership-substance loved) + the kingdom-inversion-substance (*he that is greatest among you shall be your servant*) — read against the wisdom-stream''s direct articulation of the pride-and-religious-status architecture in Sirach (Ecclesiasticus). Four moves: Sirach 10:14 names the Yahuah-casting-down-thrones-of-proud-princes substance the kingdom-inversion at Matt 23:12 walks-from; Sirach 3:18 names the greater-you-are-more-humble-thyself substance the King names at Matt 23:11; Sirach 7:4 names the seek-not-preeminence substance the King walks-against at Matt 23:6; Sirach 32:1 names THE direct verbal-anchor for the master-of-the-feast-lift-not-thyself-up substance the King walks-against at Matt 23:6''s *uppermost rooms at feasts*. The framework reads the cluster against the inherited-Christian-pulpit''s collapse of the wisdom-stream into mere-piety-literature — Sirach carries the same Father''s-voice the Tanakh-prophets and the King walk-from, and the kingdom-inversion-substance is the same substance the prophet-Mishlei (Proverbs) walks at Proverbs 16:18 and 29:23, the apostle-Ya''aqov (James) walks at James 4:6, 10, the apostle-Kefa (Peter) walks at 1 Peter 5:5-6, and the King walks at the foot-washing-substance of John 13:13-14. The system-not-people posture holds throughout — the substance the King walks-against is the leadership-substance-of-religious-status, NOT the people the leadership-substance victimizes.',
       sv.verse_id, ev.verse_id, 'complete_study', 337
  FROM _s155_xref_lookup sv, _s155_xref_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 23 AND sv.verse_number = 1
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 23 AND ev.verse_number = 12
ON CONFLICT (slug) DO NOTHING;

-- Thread 2 (sort 338): the-corrupted-priesthood-and-false-credentialing-in-testaments-of-levi-and-wisdom-stream
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'the-corrupted-priesthood-and-false-credentialing-in-testaments-of-levi-and-wisdom-stream',
       'The corrupted-priesthood and false-credentialing architecture — Testaments of Levi + 1 Enoch + Wisdom of Solomon witness to the first three woes at Matt 23:13-22 (FRAMEWORK-MAJOR)',
       'Matt 23:13-22''s first-three-woes — the leadership-substance shutting-up-the-kingdom-of-heaven-against-men (v.13), the framework-major-direct-diagnostic of the false-inclusion-gospel at v.15 (*ye compass sea and land to make one proselyte, and when he is made, ye make him twofold more the child of Gehinnom (Gehenna) than yourselves* — the prototype-substance the apostle-Sha''ul (Paul)''s letter-to-the-Galatians walks-against, the same diagnostic operating in five costumes by the contrary-to-Torah-test: Pharisaic-rabbinic through ADDITION + Galatian-agitators through INVERSION + modern-institutional-Christianity through SUBTRACTION + modern-Hebrew-Roots-false-inclusion through COLLAPSE + Islam through TRANSFER), and the third-woe at vv.16-22 (the Pharisaic-oath-distinction-substance against the Torah''s-direct-substance) — read against the wisdom-stream''s direct articulation of the corrupted-priesthood and false-credentialing architecture. Four moves: Testaments XII Levi (file ch 17, canonical Testament of Levi 16) names the deal-lawlessly-with-Yashar''el (Israel)-and-veil-of-the-temple-rent substance — the wisdom-stream''s prefiguring of the substance walking-toward the historical-fulfillment at Matt 27:51; Testaments XII Levi (file ch 20, canonical Testament of Levi 17) names THE direct verbal-anchor for the priests-(who-are)-idolaters-adulterers-lovers-of-money-proud-lawless-lascivious substance — the wisdom-stream had-named the corrupted-priesthood-substance centuries before the gospel-pivot articulated the seven-woes against the same substance; 1 Enoch 99:2 names the pervert-the-words-of-uprightness-and-transform-themselves-into-sinners substance — the substance the proselyte made-twofold-the-child-of-Gehinnom (Gehenna) is converted-into; Wisdom of Solomon 6:4 names the ministers-of-the-kingdom-have-not-judged-aright-nor-kept-the-law substance — the wisdom-stream''s direct articulation of the contrary-to-Torah-test the apostle-Yochanan (John) names at 1 John 2:3-4 the framework applies-against any system claiming covenant-standing while teaching contrary-to-the-Torah-substance. The framework reads the cluster as FRAMEWORK-MAJOR for the *Pharisaic-leadership-system = first costume of the antichrist architecture* diagnostic per the *Judaizer Error* section of framework-deep.md — the wisdom-stream and the gospel cohere at the architecture of the corrupted-priesthood-as-the-substance-the-King-walks-against. The system-not-people posture is non-negotiable — the substance is the leadership-substance, NOT the Yahudim (Jews)-as-a-people categorically; the King-of-Yashar''el (Israel) is himself a Yahudi (Jew); the apostles are Yahudim (Jews); the multitudes the King addresses at v.1 are Yahudim (Jews); the lament-substance at vv.37-39 walks the gathering-substance the leadership-substance has-kept-the-people-from.',
       sv.verse_id, ev.verse_id, 'complete_study', 338
  FROM _s155_xref_lookup sv, _s155_xref_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 23 AND sv.verse_number = 13
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 23 AND ev.verse_number = 22
ON CONFLICT (slug) DO NOTHING;

-- Thread 3 (sort 339): swearing-and-the-faithful-yes-and-nay-in-sirach
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'swearing-and-the-faithful-yes-and-nay-in-sirach',
       'Swearing and the faithful yes-and-nay — Sirach''s wisdom-stream witness to the third-woe at Matt 23:16-22',
       'Matt 23:16-22''s third-woe — the Pharisaic-rabbinic-elaborate-distinction-binding-and-non-binding-oaths-substance (*whosoever shall swear by the temple, it is nothing; but whosoever shall swear by the gold of the temple, he is a debtor* + *whosoever shall swear by the altar, it is nothing; but whosoever shall swear by the gift that is upon it, he is a debtor*) walking-against the Torah''s-direct-substance at Vayikra (Leviticus) 19:12, Bamidbar (Numbers) 30:2, and Devarim (Deuteronomy) 23:21-23 (every-vow-binds, every-oath-counts) — the same substance the King-of-Yashar''el (Israel) had-already-walked at Matt 5:33-37 (*swear not at all*) and the apostle-Ya''aqov (James) walks at James 5:12 — read against the wisdom-stream''s direct articulation of the swearing-substance the Pharisaic-casuistic-distinction-substance walks-against. Three moves: Sirach 23:9 names the accustom-not-thy-mouth-to-swearing substance directly; Sirach 23:11 names the man-that-useth-much-swearing-shall-be-filled-with-iniquity substance — the seriousness of every-oath the wisdom-stream names; Sirach 27:14 names the talk-of-him-that-sweareth-much substance — the brawls-substance the wisdom-stream warns against. The framework reads the cluster as the wisdom-stream''s direct corroboration of the substance the King names at vv.16-22 — the Pharisaic-oral-tradition-substance built-the-casuistic-distinction-substance against-the-wisdom-stream and against-the-Torah-substance directly; the wisdom-stream and the Torah and the gospel and the apostolic-substance all cohere at the every-oath-counts-substance. The substance the King walks at Matt 5:37 (*let your communication be, Yea, yea; Nay, nay*) is the substance the wisdom-stream had-named at Sirach 23 and the apostle-Ya''aqov (James) walks at James 5:12 — the same Father''s-voice walks-across the Tanakh-and-wisdom-stream-and-gospel-and-apostolic-substance.',
       sv.verse_id, ev.verse_id, 'complete_study', 339
  FROM _s155_xref_lookup sv, _s155_xref_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 23 AND sv.verse_number = 16
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 23 AND ev.verse_number = 22
ON CONFLICT (slug) DO NOTHING;

-- Thread 4 (sort 340): the-double-heart-and-two-faces-in-sirach-testaments-of-asher-and-wisdom-of-solomon
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'the-double-heart-and-two-faces-in-sirach-testaments-of-asher-and-wisdom-of-solomon',
       'The double-heart and two-faces architecture — Sirach + Testaments of Asher + Wisdom of Solomon witness to the fourth-fifth-sixth-woes at Matt 23:23-28',
       'Matt 23:23-28''s fourth-and-fifth-and-sixth-woes — the fourth-woe at vv.23-24 (*ye pay tithe of mint and anise and cummin, and have omitted the weightier matters of the law, judgment, mercy, and faith: these ought ye to have done, and not to leave the other undone*, walking the Tanakh-prophetic-summary-substance the prophet-Mikhah (Micah) had-named at Micah 6:8 with the both-and architecture preserved against-the-post-Reformation-collapse of the Torah into the weightier-matters-alone; *strain at a gnat, and swallow a camel* naming both unclean-animals per Vayikra (Leviticus) 11:4-7 and 11:20-23); the fifth-woe at vv.25-26 (the outside-of-the-cup-substance against the inside-full-of-extortion-and-excess); and the sixth-woe at vv.27-28 (*ye are like unto whited sepulchres ... within full of dead men''s bones* — the leadership-substance is itself the corpse-defilement the whitewash-of-the-tombs-before-Pesach (Passover) was warning against per the Torah''s-substance at Bamidbar (Numbers) 19:11-22) — read against the wisdom-stream''s direct articulation of the double-heart and two-faces architecture. Five moves: Sirach 1:28 names the come-not-with-a-double-heart substance directly; Sirach 1:29 names THE direct verbal-anchor for the be-not-an-hypocrite-in-the-sight-of-men substance; Testaments XII Asher (file ch 67, canonical Asher 3:1) names THE direct verbal-anchor for the wear-not-two-faces-of-goodness-and-wickedness substance — the whited-sepulchres-substance the wisdom-stream had-named centuries before the King names it at Matt 23:27-28; Testaments XII Asher (file ch 69, canonical Asher 5:2) names the double-faced-guilty-of-twofold-sin substance; Wisdom of Solomon 5:8 names the post-judgment-revealing of the what-has-pride-profited-us-or-riches-with-our-vaunting substance — the inside-full-of-extortion-and-excess at vv.25-26 the day-of-vindication-of-the-righteous-will-reveal. The framework reads the cluster in continuity with the heart-defilement-substance the King walks-from at Matt 15:10-20 and the Tanakh-substance the prophet-Shemu''el (Samuel) walks at 1 Samuel 16:7 (*Yahuah (the LORD) looketh on the heart*) and the prophet-Yechezk''el (Ezekiel) walks at Ezekiel 13:10-12 (*daubed it with untempered morter*). The wisdom-stream and the Tanakh-prophets and the gospel cohere at the inside-substance-the-Father-reads-from architecture. The system-not-people posture holds — the substance is the leadership-substance''s two-faces, NOT the people-substance the leadership-substance victimizes.',
       sv.verse_id, ev.verse_id, 'complete_study', 340
  FROM _s155_xref_lookup sv, _s155_xref_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 23 AND sv.verse_number = 23
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 23 AND ev.verse_number = 28
ON CONFLICT (slug) DO NOTHING;

-- Thread 5 (sort 341): the-blood-of-hevel-crying-and-the-mother-hen-gathering-in-1-enoch-and-2-esdras
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'the-blood-of-hevel-crying-and-the-mother-hen-gathering-in-1-enoch-and-2-esdras',
       'The blood of Hevel (Abel) crying and the mother-hen gathering — 1 Enoch 22 + 2 Esdras (4 Ezra) 1''s wisdom-stream witness to the seventh-woe at Matt 23:29-36 and the lament at vv.37-39 (FRAMEWORK-MAJOR)',
       'Matt 23:29-39''s seventh-woe and lament — the leadership-substance builds-the-tombs-of-the-prophets the same leadership-substance''s-fathers killed; *fill ye up then the measure of your fathers*; *ye serpents, ye generation of vipers* walking the seed-of-the-serpent-substance from Bereshit (Genesis) 3:15 and the wheat-and-tares-substance the King had-walked at Matt 13:24-30, 36-43 (the seed-war-substance walked-into-the-leadership-substance, NOT the Yahudim (Jews)-as-a-people categorically); *from the blood of righteous Hevel (Abel) unto the blood of Zecharyah (Zechariah) son of Berekhyahu (Barachias)* walking the WHOLE-Tanakh-prophet-killing-substance from Bereshit (Genesis) 4:8-10 (with the *voice of thy brother''s blood crieth from the ground* substance) through 2 Divrei HaYamim (Chronicles) 24:20-22 closing the Hebrew-canon-order; *all these things shall come upon this generation* walking-toward the 70 CE Roman destruction of the Second-Temple the King will-make-explicit at Matt 24:1-2; and the lament at vv.37-39 — *O Yerushalayim (Jerusalem), Yerushalayim (Jerusalem) ... how often would I have gathered thy children together, even as a hen gathereth her chickens under her wings, and ye would not! Behold, your house is left unto you desolate. For I say unto you, Ye shall not see me henceforth, till ye shall say, Blessed is he that cometh in the name of Yahuah (the LORD)* — read against the wisdom-stream''s direct articulation of the Hevel-(Abel)-blood-crying-from-the-ground architecture and the prophets-slain-house-desolate-mother-hen-gathering architecture. Five moves: 1 Enoch 22:7 names the prison-of-the-angels substance — the framework''s reading-context for the *damnation of Gehenna* at v.33 (NOT the inherited-Christian-Augustinian doctrine of eternal-conscious-torture-in-fire-for-the-merely-uninformed; the substance is the prison-of-the-angels-and-the-post-judgment-divisions per 1 Enoch 22 and the wheat-and-tares-substance the tares are bound and burned at the harvest); 1 Enoch 22:14 names THE direct wisdom-stream verbal-anchor for the spirit-of-Hevel-(Abel)-makes-suit-against-Qayin (Cain) substance at v.35; 2 Esdras (4 Ezra) 1:30 names THE direct wisdom-stream verbal-anchor for the *I gathered you together, as a hen gathers her chickens under her wings* substance at v.37 — the SAME hen-gathers-her-chickens-under-her-wings figure-of-speech the King-of-Yashar''el (Israel) speaks-with-the-Father''s-own-voice at the lament; 2 Esdras (4 Ezra) 1:32 names THE direct wisdom-stream verbal-anchor for the *I sent prophets, whom you have taken and slain* substance at v.34 and the prophet-killing-pattern at vv.35-36; 2 Esdras (4 Ezra) 1:33 names THE direct wisdom-stream verbal-anchor for the *Your house is desolate* substance at v.38. The framework reads the cluster as FRAMEWORK-MAJOR — the wisdom-stream and the Tanakh-prophets and the gospel-pivot all walk the same Father''s-voice across the prophet-killing-pattern, the house-left-desolate-substance, and the Father-as-mother-bird-gathering-the-children-under-the-wings-substance. The lament-substance walks the gathering-substance EVEN-at-the-moment-of-the-substantial-judgment of the leadership-substance the seven-woes have-walked-out — the substantial-judgment of the false-shepherds is the substance that-clears-the-way for the True-Shepherd''s-gathering per the prophet-Yechezk''el (Ezekiel) at Ezekiel 34:1-31. The substance walks-toward the surviving-third-substance the prophet-Zekharyah (Zechariah) walks at Zechariah 13:8-9 (*they shall call on my name, and I will hear them*) and the look-upon-me-whom-they-have-pierced substance at Zechariah 12:10. The framework reads the substance in continuity with Red Line #11''s ingathering-of-the-paternal-blood-remnant-of-all-twelve-tribes architecture — the lament is not the Father''s-categorical-rejection of Yerushalayim (Jerusalem); the lament is the Father''s-tender-heart walking-the-gathering-substance the wild-olive-descendants-of-the-broken-off will-walk-toward through the journey-the-prophets-named (gathered-out-of-the-nations -> brought-under-the-rod -> brought-into-the-new-covenant -> grafted-into-the-natural-root-of-the-fathers).',
       sv.verse_id, ev.verse_id, 'complete_study', 341
  FROM _s155_xref_lookup sv, _s155_xref_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 23 AND sv.verse_number = 29
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 23 AND ev.verse_number = 39
ON CONFLICT (slug) DO NOTHING;

