-- ---------------------------------------------------------------------
-- Verification block.
-- ---------------------------------------------------------------------
DO $verify$
DECLARE
  v_xref_inserted INT;
  v_thread_inserted INT;
  v_member_inserted INT;
BEGIN
  SELECT count(*) INTO v_xref_inserted FROM cross_references x
    JOIN _s155_xref_lookup sv ON sv.verse_id = x.source_verse_id
   WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 23
     AND x.tier_required = 'extras' AND x.source = 'manual';

  SELECT count(*) INTO v_thread_inserted FROM cross_reference_threads
   WHERE slug IN (
     'the-pride-and-religious-status-architecture-in-sirach',
     'the-corrupted-priesthood-and-false-credentialing-in-testaments-of-levi-and-wisdom-stream',
     'swearing-and-the-faithful-yes-and-nay-in-sirach',
     'the-double-heart-and-two-faces-in-sirach-testaments-of-asher-and-wisdom-of-solomon',
     'the-blood-of-hevel-crying-and-the-mother-hen-gathering-in-1-enoch-and-2-esdras'
   );

  SELECT count(*) INTO v_member_inserted
    FROM cross_reference_thread_members m
    JOIN cross_reference_threads t ON t.id = m.thread_id
   WHERE t.slug IN (
     'the-pride-and-religious-status-architecture-in-sirach',
     'the-corrupted-priesthood-and-false-credentialing-in-testaments-of-levi-and-wisdom-stream',
     'swearing-and-the-faithful-yes-and-nay-in-sirach',
     'the-double-heart-and-two-faces-in-sirach-testaments-of-asher-and-wisdom-of-solomon',
     'the-blood-of-hevel-crying-and-the-mother-hen-gathering-in-1-enoch-and-2-esdras'
   );

  RAISE NOTICE 'S155 Matt 23 verify: extras xrefs from canon/matthew/23 = %, threads = %, members = %',
    v_xref_inserted, v_thread_inserted, v_member_inserted;

  IF v_thread_inserted <> 5 THEN
    RAISE EXCEPTION 'Expected 5 threads inserted; got %', v_thread_inserted;
  END IF;
  IF v_xref_inserted < 21 THEN
    RAISE EXCEPTION 'Expected at least 21 Matt-23 extras xrefs; got %', v_xref_inserted;
  END IF;
  IF v_member_inserted < 21 THEN
    RAISE EXCEPTION 'Expected at least 21 thread members; got %', v_member_inserted;
  END IF;
END;
$verify$;

COMMIT;
